//! Rank/mint/stake state machine analogue for the Vegeta S3 XENCrypto family.
use cosmwasm_std::{entry_point,to_json_binary,Addr,Binary,Deps,DepsMut,Env,MessageInfo,Response,StdError,StdResult,Uint128};use cw_storage_plus::{Item,Map};use schemars::JsonSchema;use serde::{Deserialize,Serialize};use thiserror::Error;
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct InstantiateMsg{pub genesis_ts:u64}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum ExecuteMsg{ClaimRank{term_days:u64},ClaimMintReward{},ClaimMintRewardAndShare{other:String,pct:u8},ClaimMintRewardAndStake{pct:u8,term_days:u64},Stake{amount:Uint128,term_days:u64},Withdraw{},Transfer{recipient:String,amount:Uint128}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]#[serde(rename_all="snake_case")]pub enum QueryMsg{GlobalRank{},UserMint{address:String},UserStake{address:String},Balance{address:String}}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct Global{pub genesis_ts:u64,pub global_rank:u64,pub total_supply:Uint128,pub total_staked:Uint128}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct MintRecord{pub rank:u64,pub maturity:u64}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct StakeRecord{pub amount:Uint128,pub maturity:u64}
#[derive(Serialize,Deserialize,Clone,Debug,PartialEq,Eq,JsonSchema)]pub struct AmountResponse{pub amount:Uint128}
const GLOBAL:Item<Global>=Item::new("global");const USER_MINTS:Map<&str,MintRecord>=Map::new("user_mints");const USER_STAKES:Map<&str,StakeRecord>=Map::new("user_stakes");const BALANCES:Map<&str,Uint128>=Map::new("balances");
#[derive(Error,Debug,PartialEq)]pub enum ContractError{#[error("{0}")]Std(#[from]StdError),#[error("active mint exists")]ActiveMint,#[error("mint not mature")]MintNotMature,#[error("stake not mature")]StakeNotMature,#[error("missing state")]Missing,#[error("insufficient funds")]InsufficientFunds,#[error("invalid share")]InvalidShare}
#[entry_point]pub fn instantiate(deps:DepsMut,_:Env,_:MessageInfo,msg:InstantiateMsg)->Result<Response,ContractError>{GLOBAL.save(deps.storage,&Global{genesis_ts:msg.genesis_ts,global_rank:1,total_supply:Uint128::zero(),total_staked:Uint128::zero()})?;Ok(Response::new())}
#[entry_point]pub fn execute(deps:DepsMut,env:Env,info:MessageInfo,msg:ExecuteMsg)->Result<Response,ContractError>{match msg{ExecuteMsg::ClaimRank{term_days}=>claim_rank(deps,env,info.sender,term_days),ExecuteMsg::ClaimMintReward{}=>claim_reward(deps,env,info.sender,None),ExecuteMsg::ClaimMintRewardAndShare{other,pct}=>{if pct>100{return Err(ContractError::InvalidShare)};claim_reward(deps,env,info.sender,Some((other,pct)))},ExecuteMsg::ClaimMintRewardAndStake{pct,term_days}=>claim_reward_and_stake(deps,env,info.sender,pct,term_days),ExecuteMsg::Stake{amount,term_days}=>stake(deps,env,info.sender,amount,term_days),ExecuteMsg::Withdraw{}=>withdraw(deps,env,info.sender),ExecuteMsg::Transfer{recipient,amount}=>transfer(deps,info.sender,recipient,amount)}}
fn claim_rank(deps:DepsMut,env:Env,user:Addr,term:u64)->Result<Response,ContractError>{if USER_MINTS.may_load(deps.storage,user.as_str())?.is_some(){return Err(ContractError::ActiveMint)};let mut g=GLOBAL.load(deps.storage)?;let rank=g.global_rank;g.global_rank=g.global_rank.saturating_add(1);GLOBAL.save(deps.storage,&g)?;USER_MINTS.save(deps.storage,user.as_str(),&MintRecord{rank,maturity:env.block.time.seconds().saturating_add(term.saturating_mul(86_400))})?;Ok(Response::new())}
fn claim_reward(deps:DepsMut,env:Env,user:Addr,share:Option<(String,u8)>)->Result<Response,ContractError>{let m=USER_MINTS.may_load(deps.storage,user.as_str())?.ok_or(ContractError::Missing)?;if env.block.time.seconds()<m.maturity{return Err(ContractError::MintNotMature)};let g=GLOBAL.load(deps.storage)?;let reward=Uint128::new((g.global_rank.saturating_sub(m.rank).saturating_add(1)) as u128*1_000);USER_MINTS.remove(deps.storage,user.as_str());if let Some((other,pct))=share{let other=deps.api.addr_validate(&other)?;let other_amount=reward.multiply_ratio(pct as u128,100u128);credit(deps.storage,other.as_str(),other_amount)?;credit(deps.storage,user.as_str(),reward.checked_sub(other_amount).map_err(StdError::overflow)?)?;}else{credit(deps.storage,user.as_str(),reward)?;}GLOBAL.update(deps.storage,|mut x|->StdResult<_>{x.total_supply=x.total_supply.checked_add(reward).map_err(StdError::overflow)?;Ok(x)})?;Ok(Response::new())}
fn claim_reward_and_stake(deps:DepsMut,env:Env,user:Addr,pct:u8,term:u64)->Result<Response,ContractError>{if pct>100{return Err(ContractError::InvalidShare)};let m=USER_MINTS.may_load(deps.storage,user.as_str())?.ok_or(ContractError::Missing)?;if env.block.time.seconds()<m.maturity{return Err(ContractError::MintNotMature)};let g=GLOBAL.load(deps.storage)?;let reward=Uint128::new((g.global_rank.saturating_sub(m.rank).saturating_add(1)) as u128*1_000);let stake_amount=reward.multiply_ratio(pct as u128,100u128);let liquid=reward.checked_sub(stake_amount).map_err(StdError::overflow)?;USER_MINTS.remove(deps.storage,user.as_str());if !liquid.is_zero(){credit(deps.storage,user.as_str(),liquid)?;}USER_STAKES.save(deps.storage,user.as_str(),&StakeRecord{amount:stake_amount,maturity:env.block.time.seconds().saturating_add(term.saturating_mul(86_400))})?;GLOBAL.update(deps.storage,|mut x|->StdResult<_>{x.total_supply=x.total_supply.checked_add(reward).map_err(StdError::overflow)?;x.total_staked=x.total_staked.checked_add(stake_amount).map_err(StdError::overflow)?;Ok(x)})?;Ok(Response::new())}
fn stake(deps:DepsMut,env:Env,user:Addr,amount:Uint128,term:u64)->Result<Response,ContractError>{debit(deps.storage,user.as_str(),amount)?;USER_STAKES.save(deps.storage,user.as_str(),&StakeRecord{amount,maturity:env.block.time.seconds().saturating_add(term.saturating_mul(86_400))})?;GLOBAL.update(deps.storage,|mut g|->StdResult<_>{g.total_staked=g.total_staked.checked_add(amount).map_err(StdError::overflow)?;Ok(g)})?;Ok(Response::new())}
fn withdraw(deps:DepsMut,_env:Env,user:Addr)->Result<Response,ContractError>{let s=USER_STAKES.may_load(deps.storage,user.as_str())?.ok_or(ContractError::Missing)?;USER_STAKES.remove(deps.storage,user.as_str());credit(deps.storage,user.as_str(),s.amount)?;GLOBAL.update(deps.storage,|mut g|->StdResult<_>{g.total_staked=g.total_staked.checked_sub(s.amount).map_err(StdError::overflow)?;Ok(g)})?;Ok(Response::new())}
fn transfer(deps:DepsMut,user:Addr,recipient:String,amount:Uint128)->Result<Response,ContractError>{let r=deps.api.addr_validate(&recipient)?;debit(deps.storage,user.as_str(),amount)?;credit(deps.storage,r.as_str(),amount)?;Ok(Response::new())}
fn debit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->Result<(),ContractError>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();if x<n{return Err(ContractError::InsufficientFunds)};BALANCES.save(s,a,&x.checked_sub(n).map_err(StdError::overflow)?)?;Ok(())}
fn credit(s:&mut dyn cosmwasm_std::Storage,a:&str,n:Uint128)->StdResult<()>{let x=BALANCES.may_load(s,a)?.unwrap_or_default();BALANCES.save(s,a,&x.checked_add(n).map_err(StdError::overflow)?) }
#[entry_point]pub fn query(deps:Deps,_:Env,msg:QueryMsg)->StdResult<Binary>{match msg{QueryMsg::GlobalRank{}=>to_json_binary(&GLOBAL.load(deps.storage)?),QueryMsg::UserMint{address}=>to_json_binary(&USER_MINTS.may_load(deps.storage,&address)?),QueryMsg::UserStake{address}=>to_json_binary(&USER_STAKES.may_load(deps.storage,&address)?),QueryMsg::Balance{address}=>to_json_binary(&AmountResponse{amount:BALANCES.may_load(deps.storage,&address)?.unwrap_or_default()})}}
#[cfg(test)]mod tests{use super::*;use cosmwasm_std::testing::{mock_dependencies,mock_env,mock_info};#[test]fn withdraw_before_maturity_matches_xen_close_semantics(){let mut d=mock_dependencies();let e=mock_env();instantiate(d.as_mut(),e.clone(),mock_info("x",&[]),InstantiateMsg{genesis_ts:0}).unwrap();BALANCES.save(d.as_mut().storage,"alice",&Uint128::new(10)).unwrap();execute(d.as_mut(),e.clone(),mock_info("alice",&[]),ExecuteMsg::Stake{amount:Uint128::new(10),term_days:1}).unwrap();execute(d.as_mut(),e,mock_info("alice",&[]),ExecuteMsg::Withdraw{}).unwrap();assert!(USER_STAKES.may_load(d.as_ref().storage,"alice").unwrap().is_none());assert_eq!(BALANCES.load(d.as_ref().storage,"alice").unwrap(),Uint128::new(10));assert_eq!(GLOBAL.load(d.as_ref().storage).unwrap().total_staked,Uint128::zero());}#[test]fn rank_and_mint_reward_use_global_and_user_state(){let mut d=mock_dependencies();let mut e=mock_env();instantiate(d.as_mut(),e.clone(),mock_info("x",&[]),InstantiateMsg{genesis_ts:0}).unwrap();execute(d.as_mut(),e.clone(),mock_info("alice",&[]),ExecuteMsg::ClaimRank{term_days:1}).unwrap();e.block.time=e.block.time.plus_seconds(86_400);execute(d.as_mut(),e,mock_info("alice",&[]),ExecuteMsg::ClaimMintReward{}).unwrap();assert!(BALANCES.load(d.as_ref().storage,"alice").unwrap()>Uint128::zero());}#[test]fn claim_reward_and_stake_updates_mint_stake_balance_and_global_state(){let mut d=mock_dependencies();let mut e=mock_env();instantiate(d.as_mut(),e.clone(),mock_info("x",&[]),InstantiateMsg{genesis_ts:0}).unwrap();execute(d.as_mut(),e.clone(),mock_info("alice",&[]),ExecuteMsg::ClaimRank{term_days:0}).unwrap();execute(d.as_mut(),e,mock_info("alice",&[]),ExecuteMsg::ClaimMintRewardAndStake{pct:50,term_days:1}).unwrap();assert!(USER_MINTS.may_load(d.as_ref().storage,"alice").unwrap().is_none());assert!(USER_STAKES.load(d.as_ref().storage,"alice").unwrap().amount>Uint128::zero());assert!(BALANCES.load(d.as_ref().storage,"alice").unwrap()>Uint128::zero());let g=GLOBAL.load(d.as_ref().storage).unwrap();assert!(g.total_supply>Uint128::zero());assert!(g.total_staked>Uint128::zero());}}
